#!/usr/bin/env bash
# generate-tests.sh — regenerate smoke.bats from packages.tsv.
#
# The .bats file is committed as well so contributors can read the tests
# without running this script. Re-run this whenever the manifest changes.

set -euo pipefail

HERE="$(dirname "$(readlink -f "$0")")"
MANIFEST="${HERE}/packages.tsv"
OUT="${HERE}/smoke.bats"

[[ -f "$MANIFEST" ]] || { echo "manifest not found: $MANIFEST" >&2; exit 1; }

{
cat <<'HEADER'
#!/usr/bin/env bats
# AUTOGENERATED from packages.tsv by generate-tests.sh — do not edit manually.
#
# Run with:
#   bats smoke.bats                  # serial, plain TAP
#   bats --jobs 8 smoke.bats         # parallel
#   bats -F tap smoke.bats           # explicit TAP formatter
#   bats -F junit -o results smoke.bats   # JUnit XML for CI

# We use `run --separate-stderr` which needs bats >= 1.5.0. Declaring the
# minimum suppresses the BW02 warning that otherwise fires on every test.
bats_require_minimum_version 1.5.0

setup_file() {
    export NEUROFEDORA_TESTS=1
}

# Skip the whole test if its package isn't installed (so a partial install
# doesn't produce a wall of "not installed" failures — only the install.sh
# reports those).
_require_installed() {
    local pkg="$1"
    rpm -q --quiet "$pkg" 2>/dev/null || skip "$pkg not installed"
}

HEADER

awk -F'\t' '
    /^[[:space:]]*$/  { next }
    /^[[:space:]]*#/  { next }
    NF < 3            { next }
    {
        pkg = $1; cat = $2; cmd = $3; expect = $4
        # escape double quotes and backslashes for the heredoc body
        gsub(/\\/, "\\\\", cmd);  gsub(/"/, "\\\"", cmd)
        gsub(/\\/, "\\\\", expect); gsub(/"/, "\\\"", expect)
        printf "\n"
        printf "@test \"%s (%s): %s\" {\n", pkg, cat, cmd
        printf "    _require_installed \"%s\"\n", pkg
        printf "    run --separate-stderr bash -c \"%s\"\n", cmd
        if (expect == "") {
            printf "    [ \"$status\" -eq 0 ] || { echo \"exit=$status stdout=$output stderr=$stderr\"; false; }\n"
        } else {
            # Use grep -E instead of bash [[ =~ ]] — the latter cannot handle
            # patterns with spaces (bash treats them as token separators).
            printf "    grep -qE \"%s\" <<<\"$output\\n$stderr\" || { echo \"expected /%s/ in output, got: $output $stderr\"; false; }\n", expect, expect
        }
        printf "}\n"
    }
' "$MANIFEST"
} > "$OUT"

chmod +x "$OUT"
n=$(grep -c '^@test ' "$OUT")
echo "[generate] wrote $OUT ($n tests)"
